def human_size(num_bytes: int) -> str:
    val = float(num_bytes)
    for unit in ("B", "KB", "MB", "GB"):
        if val < 1024 or unit == "GB":
            return "%.1f %s" % (val, unit)
        val /= 1024.0
    return "%.1f GB" % val


def print_table(sessions: List[Session], out_root: Path, date_mode: str) -> None:
    print("%-42s %-12s %-10s %-10s %6s  %s" % ("session_id", "tool", "first", "last", "events", "title"))
    print("-" * 120)
    for s in sorted(sessions, key=lambda x: (x.last_ts or "")):
        target = out_root / s.date(date_mode) / ("%s__%s.jsonl" % (s.tool, s.sid))
        mark = "*" if target.exists() else " "
        print(
            "%-42s %-12s %-10s %-10s %6d  %s %s"
            % (s.sid[:42], s.tool, local_date(s.first_ts), local_date(s.last_ts), len(s.events), mark, (s.title or "")[:40])
        )


def select(
    sessions: List[Session],
    session_ids: List[str],
    today: bool,
    since: Optional[str],
    all_flag: bool,
    latest: bool,
) -> List[Session]:
    chosen = sessions
    if session_ids:
        chosen = [s for s in chosen if s.sid in session_ids]
    if today:
        today_str = datetime.now().strftime("%Y-%m-%d")
        chosen = [s for s in chosen if local_date(s.last_ts) == today_str]
    if since:
        cutoff = parse_ts(since + "T00:00:00+00:00") if len(since) == 10 else parse_ts(since)
        if cutoff is not None:
            picked = []
            for s in chosen:
                dt = parse_ts(s.last_ts)
                if dt is not None and dt >= cutoff:
                    picked.append(s)
            chosen = picked
    if latest:
        chosen = sorted(chosen, key=lambda s: s.last_ts or "")[-1:]
    if not (session_ids or today or since or all_flag or latest):
        return sorted(chosen, key=lambda s: s.last_ts or "")
    return sorted(chosen, key=lambda s: s.last_ts or "")


def sync_to_repo(out_root: Path, login: str, repo: Path, confirm: bool) -> None:
    dst = repo / "logs" / login
    print("\n把 logs 同步进比赛仓：%s" % dst)
    if not confirm:
        print("  （预览）将覆盖 %s 下的同名文件" % dst)
        return
    dst.mkdir(parents=True, exist_ok=True)
    for manifest_src in [out_root / "manifest.json"]:
        if manifest_src.is_file():
            shutil.copy2(str(manifest_src), str(dst / "manifest.json"))
    for src_dir in sorted(out_root.iterdir()):
        if not src_dir.is_dir() or src_dir.name.startswith("."):
            continue
        if not re.match(r"^\d{4}-\d{2}-\d{2}$", src_dir.name):
            continue
        target_dir = dst / src_dir.name
        target_dir.mkdir(parents=True, exist_ok=True)
        for src_file in src_dir.glob("*.jsonl"):
            shutil.copy2(str(src_file), str(target_dir / src_file.name))
    print("  已同步。接下来在比赛仓执行：")
    print("    git add logs/")
    print('    git commit -s -m "logs: sync AI sessions"')
    print("    git push")


def cmd_scrub(out_root: Path, redactor: Redactor, confirm: bool) -> int:
    total = 0
    files = 0
    for f in sorted(out_root.glob("*/*.jsonl")) + sorted(out_root.glob(".superseded/*/*.jsonl")):
        try:
            lines = f.read_text(encoding="utf-8", errors="replace").splitlines()
        except Exception:
            continue
        changed = False
        out_lines: List[str] = []
        for line in lines:
            if not line.strip():
                continue
            try:
                ev = json.loads(line)
            except Exception:
                out_lines.append(line)
                continue
            nv, cnt = redactor.value(ev)
            if cnt:
                nv["redacted_count"] = int(nv.get("redacted_count", 0)) + cnt
                total += cnt
                changed = True
            out_lines.append(json.dumps(nv, ensure_ascii=False))
        if changed:
            files += 1
            if confirm:
                f.write_text("\n".join(out_lines) + "\n", encoding="utf-8")
    print("脱敏：%d 个文件、共 %d 处%s" % (files, total, "" if confirm else "（预览，未写盘）"))
    return 0


def main(argv: Optional[List[str]] = None) -> int:
    try:
        sys.stdout.reconfigure(encoding="utf-8", errors="replace")  # type: ignore[attr-defined]
    except Exception:
        pass

    ap = argparse.ArgumentParser(
        description="导出 AI Coding 日志到比赛仓库 logs/<login>/ 下（默认预览，--confirm 才写盘）",
        formatter_class=argparse.RawTextHelpFormatter,
    )
    ap.add_argument("--list", action="store_true", help="只列出候选会话，不写盘")
    ap.add_argument("--list-outside", action="store_true", help="同时列出被工作区闸门排除的会话")
    ap.add_argument("--session", action="append", default=[], help="指定 session_id（可重复）")
    ap.add_argument("--latest", action="store_true", help="只导出最近一个会话")
    ap.add_argument("--today", action="store_true", help="只导出今天结束的会话")
    ap.add_argument("--since", help="只导出该日期（YYYY-MM-DD）之后结束的会话")
    ap.add_argument("--all", action="store_true", help="导出工作区内全部会话")
    ap.add_argument("--confirm", action="store_true", help="真正写入；缺省只预览")
    ap.add_argument("--overwrite", action="store_true", help="覆盖已存在的同会话文件（默认跳过）")
    ap.add_argument("--tool", default="all", help="只处理某工具：mimocode / claude-code / codex / all")
    ap.add_argument("--out", help="输出根目录（默认：本脚本目录/logs/<login>）")
    ap.add_argument("--repo", help="比赛仓路径（用于 --sync-repo）")
    ap.add_argument("--sync-repo", action="store_true", help="导出后把 logs 同步进比赛仓（配合 --confirm）")
    ap.add_argument("--workspace", help="openvela 工作区根目录（默认：向上找 .repo，找不到则用脚本目录）")
    ap.add_argument("--allow-outside", action="store_true", help="允许导出工作区之外的会话（不建议）")
    ap.add_argument("--team-id", help="覆盖 TEAM_ID")
    ap.add_argument("--login", help="覆盖 GITHUB_LOGIN")
    ap.add_argument("--env-file", help="contest-collector.env 路径")
    ap.add_argument("--date-mode", choices=["last", "start"], default="last", help="按会话最后/首个事件日期分目录")
    ap.add_argument("--max-io", type=int, default=0, help="单条工具出入参最大字符数，0=不截断")
    ap.add_argument("--include-compaction", action="store_true", help="把压缩摘要作为 system 事件导出")
    ap.add_argument("--no-redact", action="store_true", help="关闭密钥脱敏（不建议）")
    ap.add_argument("--keep-old", action="store_true", help="保留旧快照/旧工具名的同会话文件（默认移到 .superseded/）")
    ap.add_argument("--validate", action="store_true", help="只校验 logs 目录")
    ap.add_argument("--scrub-existing", action="store_true", help="只对 logs 下已有文件做脱敏")
    ap.add_argument("--no-auto-validate", action="store_true", help="写盘后不做自动校验")
    args = ap.parse_args(argv)

    env_file = Path(args.env_file).expanduser() if args.env_file else CLAUDE_ENV_FILE
    team_id, login = load_identity(env_file)
    team_id = args.team_id or team_id
    login = args.login or login

    workspace = Path(args.workspace).expanduser() if args.workspace else find_workspace(SCRIPT_DIR)
    out_root = Path(args.out).expanduser() if args.out else (SCRIPT_DIR / "logs" / login)
    out_root = out_root.resolve()
    member_dir = out_root

    redactor = Redactor(load_redaction_rules(member_dir), enabled=not args.no_redact)

    print("=== openvela AI 日志导出 ===")
    print("team_id      : %s" % team_id)
    print("github_login : %s" % login)
    print("workspace    : %s" % workspace)
    print("输出目录     : %s" % out_root)
    print("")

    if args.validate:
        rep = validate_logs(out_root, team_id, login)
        print("校验：%d 个文件 / %d 条事件" % (rep.files, rep.events))
        rep.dump()
        print("结果：%s" % ("FAIL" if rep.errors else ("WARN" if rep.warnings else "PASS")))
        return 1 if rep.errors else 0

    if args.scrub_existing:
        return cmd_scrub(out_root, redactor, args.confirm)

    # ---------- 采集 ----------
    wanted_tool = (args.tool or "all").lower()
    all_sessions: List[Session] = []
    notes: List[str] = []
    outside_count = 0

    if wanted_tool in ("all", "mimocode"):
        sess, skipped, err = load_mimocode_sessions(
            workspace, args.allow_outside, args.max_io, args.include_compaction
        )
        outside_count = skipped
        if err:
            notes.append(err)
        all_sessions.extend(sess)

    if wanted_tool in ("all", "claude-code", "opencode", "codex", "cursor", "kiro"):
        staging_sessions, err = load_staging_sessions(login)
        if err and wanted_tool != "all":
            notes.append(err)
        if wanted_tool == "all":
            all_sessions.extend(staging_sessions)
        else:
            all_sessions.extend([s for s in staging_sessions if s.tool == wanted_tool])

    if wanted_tool in ("all", "codex"):
        codex_sessions, err = load_codex_sessions(workspace, args.allow_outside)
        if err:
            notes.append(err)
        all_sessions.extend(codex_sessions)

    for n in notes:
        print("[注意] " + n)

    # 去重（同 session_id + tool 只留事件最多的一个来源）
    best: Dict[Tuple[str, str], Session] = {}
    for s in all_sessions:
        key = (s.tool, s.sid)
        if key not in best or len(s.events) > len(best[key].events):
            best[key] = s
