        return 0

    chosen = select(sessions, args.session, args.today, args.since, args.all, args.latest)
    if not chosen:
        print("没有匹配的会话。可先用 --list 查看。")
        return 0

    print("\n本次将导出 %d 个会话：" % len(chosen))
