                "role": "tool",
                "tool_name": call_names.get(cid) or "<result>",
                "tool_call_id": cid,
                "input": None,
                "output": text if text else None,
            }
            if data.get("isError") or msg.get("isError"):
                item["is_error"] = True
            out.append(item)

    return out


